WITH filtered AS (SELECT *, CASE WHEN is_remote THEN 'Yes' ELSE 'No' END AS is_remote_label, COALESCE(full_name, 'N/A') AS full_name_filled FROM employees WHERE job_title IS DISTINCT FROM 'Analyst' AND manager_id IS NOT NULL) SELECT *, MAX(salary) OVER (PARTITION BY manager_id) AS manager_id_max_salary, AVG(salary) OVER w_part AS salary_avg_5_prior, ROW_NUMBER() OVER (ORDER BY salary DESC, id ASC) AS event_seq FROM filtered WINDOW w_part AS (PARTITION BY job_title ORDER BY hire_date ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING)
